using DadoHome.Api.Data;using Microsoft.EntityFrameworkCore;
namespace DadoHome.Api.Orders;
public class ReservationExpiryWorker(IServiceScopeFactory scopes,IConfiguration cfg,ILogger<ReservationExpiryWorker> log):BackgroundService{
 protected override async Task ExecuteAsync(CancellationToken stoppingToken){var minutes=Math.Clamp(cfg.GetValue<int?>("Orders:ReservationMinutes")??20,5,120);while(!stoppingToken.IsCancellationRequested){try{using var scope=scopes.CreateScope();var db=scope.ServiceProvider.GetRequiredService<DadoDbContext>();var cutoff=DateTime.UtcNow.AddMinutes(-minutes);var ids=await db.Orders.Where(x=>x.Status=="Created"&&x.StockState=="Reserved"&&x.CreatedAt<=cutoff).Select(x=>x.Id).Take(100).ToListAsync(stoppingToken);foreach(var id in ids)await Expire(db,id,stoppingToken);}catch(Exception ex){log.LogError(ex,"Failed to expire order reservations");}await Task.Delay(TimeSpan.FromMinutes(1),stoppingToken);}}
 static async Task Expire(DadoDbContext db,Guid id,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable,ct);var order=await db.Orders.SingleOrDefaultAsync(x=>x.Id==id,ct);if(order is null||order.Status!="Created"||order.StockState!="Reserved"){await tx.RollbackAsync(ct);return;}var items=await db.OrderItems.Where(x=>x.OrderId==id).ToListAsync(ct);var productIds=items.Select(x=>x.ProductId).Distinct().ToList();var products=await db.Products.Where(x=>productIds.Contains(x.Id)).ToDictionaryAsync(x=>x.Id,ct);foreach(var item in items)if(products.TryGetValue(item.ProductId,out var product))product.Stock+=Math.Max(0,item.Quantity-item.ReturnedQuantity);order.StockState="Released";order.StockReleasedAt=DateTime.UtcNow;order.Status="Cancelled";var pending=await db.Payments.Where(x=>x.OrderId==id&&x.Status=="Pending").ToListAsync(ct);foreach(var payment in pending)payment.Status="Expired";db.AuditLogs.Add(new AuditLog{Id=Guid.NewGuid(),ActorId="reservation-worker",Role="System",Action="ORDER_RESERVATION_EXPIRED_STOCK_RELEASED",Entity="Order",EntityId=id.ToString()});await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);}
}
